#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
KARAOKE GLASANJE - lokalni server za glasanje preko QR koda.
Na kraju veceri gosti na mobitelu ocijene SVE izvodjace, a program proglasi 3., 2. i 1. mjesto.
Radi bez interneta: gosti moraju biti na istoj Wi-Fi mrezi kao ovo racunalo.
Pokretanje: dvoklik na karaoke.py  (ili u terminalu: python karaoke.py)
"""
import base64
import json
import os
import secrets
import socket
import sys
import threading
import time
import webbrowser
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

PORTS = [int(os.environ["PORT"])] if os.environ.get("PORT") else [8080, 8000, 8888, 5000, 8081]
DIR = os.path.dirname(os.path.abspath(__file__))
DATA_FILE = os.path.join(DIR, "karaoke_podaci.json")
KEY = secrets.token_hex(3)
LOCK = threading.Lock()
QRLIB = base64.b64decode("").decode("utf-8")
REVEAL_SECONDS = 13  # koliko traje otkrivanje 3. > 2. > odbrojavanje > 1. na ekranu


# ------------------------------------------------------------------ podaci
def default_state():
    return {"title": "Karaoke večer", "performers": [], "phase": "waiting", "reveal": None,
            "wifi": {"ssid": "", "password": "", "show": True}}


def load_state():
    try:
        with open(DATA_FILE, "r", encoding="utf-8") as f:
            s = json.load(f)
        base = default_state()
        base.update(s)
        if base.get("phase") not in ("waiting", "open", "closed"):
            base["phase"] = "waiting"
        return base
    except Exception:
        return default_state()


STATE = load_state()


def save_state():
    tmp = DATA_FILE + ".tmp"
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(STATE, f, ensure_ascii=False, indent=1)
        os.replace(tmp, DATA_FILE)
    except Exception as e:
        print("Upozorenje: ne mogu spremiti podatke:", e)


def find(pid):
    for p in STATE["performers"]:
        if p["id"] == pid:
            return p
    return None


def stats(p):
    vals = list(p["votes"].values())
    n = len(vals)
    return n, (sum(vals) / n if n else 0.0)


def ranked():
    rows = []
    for i, p in enumerate(STATE["performers"]):
        n, avg = stats(p)
        if n:
            rows.append((p, n, avg, i))
    rows.sort(key=lambda r: (-r[2], -r[1], r[3]))
    return [(p, n, a) for p, n, a, _ in rows]


def voter_count():
    v = set()
    for p in STATE["performers"]:
        v.update(p["votes"].keys())
    return len(v)


def reveal_public():
    r = STATE.get("reveal")
    if not r:
        return None
    out = dict(r)
    out["age"] = max(0.0, time.time() - r.get("at", 0))
    return out


def public_state(voter):
    return {"title": STATE["title"], "phase": STATE["phase"], "reveal": reveal_public(),
            "voters": voter_count(),
            "performers": [{"id": p["id"], "name": p["name"], "song": p["song"],
                            "my": p["votes"].get(voter) if voter else None}
                           for p in STATE["performers"]]}


def admin_state():
    perf = []
    for p in STATE["performers"]:
        n, avg = stats(p)
        perf.append({"id": p["id"], "name": p["name"], "song": p["song"], "n": n, "avg": avg})
    return {"title": STATE["title"], "phase": STATE["phase"], "reveal": reveal_public(),
            "performers": perf, "voters": voter_count(),
            "ranking": [{"id": p["id"], "name": p["name"], "song": p["song"], "n": n, "avg": a}
                        for p, n, a in ranked()],
            "guestUrl": GUEST_URL, "adminUrl": GUEST_URL + "admin?key=" + KEY,
            "ips": IPS, "phones": len(SEEN), "wifi": STATE.get("wifi"), "wifiQr": wifi_qr_text()}


def admin_action(d):
    global GUEST_URL
    a = d.get("action")
    if a == "title":
        STATE["title"] = str(d.get("title", ""))[:60]
    elif a == "add":
        name = str(d.get("name", "")).strip()[:40]
        if not name:
            return "Upiši ime."
        STATE["performers"].append({"id": secrets.token_hex(4), "name": name,
                                    "song": str(d.get("song", "")).strip()[:70], "votes": {}})
    elif a == "del":
        STATE["performers"] = [p for p in STATE["performers"] if p["id"] != d.get("id")]
    elif a == "open":
        if not STATE["performers"]:
            return "Prvo dodaj natjecatelje."
        STATE["phase"], STATE["reveal"] = "open", None
    elif a == "close":
        STATE["phase"] = "closed"
    elif a == "reopen_waiting":
        STATE["phase"], STATE["reveal"] = "waiting", None
    elif a == "reveal":
        r = ranked()
        if not r:
            return "Još nema glasova."
        STATE["phase"] = "closed"
        STATE["reveal"] = {"id": secrets.token_hex(4), "at": time.time(),
                           "places": [{"place": i + 1, "name": p["name"], "song": p["song"],
                                       "avg": avg, "n": n} for i, (p, n, avg) in enumerate(r[:3])]}
    elif a == "hide":
        STATE["reveal"] = None
    elif a == "reset_votes":
        for p in STATE["performers"]:
            p["votes"] = {}
        STATE["reveal"], STATE["phase"] = None, "waiting"
    elif a == "reset_all":
        t, w = STATE["title"], STATE.get("wifi")
        STATE.clear()
        STATE.update(default_state())
        STATE["title"], STATE["wifi"] = t, w
    elif a == "wifi":
        STATE["wifi"] = {"ssid": str(d.get("ssid", "")).strip()[:64],
                         "password": str(d.get("password", ""))[:64],
                         "show": bool(d.get("show", True))}
    elif a == "wifi_detect":
        ssid, pw = detect_wifi()
        if not ssid:
            return "Laptop ne da pročitati Wi-Fi. Upiši ime mreže i lozinku ručno pa stisni Spremi."
        STATE["wifi"] = {"ssid": ssid, "password": pw or STATE["wifi"].get("password", ""), "show": True}
    elif a == "setip":
        ip = d.get("ip")
        if ip not in IPS:
            return "Nepoznata adresa."
        GUEST_URL = "http://%s:%d/" % (ip, PORT)
        return None
    else:
        return "Nepoznata radnja."
    save_state()
    return None


# ------------------------------------------------------------------ mreza
def lan_ip():
    for target in ("10.255.255.255", "192.168.255.255", "8.8.8.8"):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.connect((target, 1))
            ip = s.getsockname()[0]
            s.close()
            if ip and not ip.startswith("127."):
                return ip
        except Exception:
            pass
    try:
        ip = socket.gethostbyname(socket.gethostname())
        if not ip.startswith("127."):
            return ip
    except Exception:
        pass
    return "127.0.0.1"


GUEST_URL = ""
PORT = 8080
IPS = []
SEEN = set()


def all_ips():
    ips = []
    first = lan_ip()
    if first != "127.0.0.1":
        ips.append(first)
    try:
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            ip = info[4][0]
            if ip not in ips and not ip.startswith("127.") and not ip.startswith("169.254."):
                ips.append(ip)
    except Exception:
        pass
    return ips or ["127.0.0.1"]


def _run(cmd):
    import subprocess
    r = subprocess.run(cmd, shell=True, capture_output=True)
    for enc in ("utf-8", "oem", "cp852", "cp1250", "latin-1"):
        try:
            return r.stdout.decode(enc)
        except Exception:
            continue
    return ""


def _win_password(ssid):
    """Lozinka iz spremljenog Windows Wi-Fi profila."""
    import re
    out = _run('netsh wlan show profile name="%s" key=clear' % ssid.replace('"', ''))
    m = re.search(r"^\s*(Key Content|Sadr\S* klju\S*|Inhalt des Schl\S*|Contenu de la cl\S*)\s*:\s*(.+?)\s*$",
                  out, re.M | re.I)
    if m:
        return m.group(2)
    lines = out.splitlines()
    for i, ln in enumerate(lines[:-1]):
        if re.search(r"(Security key|Sigurnosni klju|Sicherheitsschl)", ln, re.I):
            nxt = lines[i + 1]
            if ":" in nxt:
                return nxt.split(":", 1)[1].strip()
    return ""


def _win_profiles():
    import re
    out = _run("netsh wlan show profiles")
    return [m.group(1).strip() for m in re.finditer(r":\s*(.+?)\s*$", out, re.M)
            if m.group(1).strip()]


def detect_wifi():
    """Pokusa procitati ime Wi-Fi mreze i lozinku s ovog racunala."""
    import re
    ssid, pw = "", ""
    try:
        if os.name == "nt":
            # 1) klasicno (na Windows 11 24H2+ trazi dozvolu za lokaciju)
            out = _run("netsh wlan show interfaces")
            m = re.search(r"^\s*SSID\s*:\s*(.+?)\s*$", out, re.M)
            if m:
                ssid = m.group(1)
            # 2) bez dozvole za lokaciju: ime aktivne mreze
            if not ssid:
                name = _run('powershell -NoProfile -Command "(Get-NetConnectionProfile | '
                            "Where-Object {$_.InterfaceAlias -match 'Wi-?Fi|WLAN|Wireless|Beži'} | "
                            'Select-Object -First 1).Name"').strip()
                if name:
                    profs = _win_profiles()
                    if name in profs:
                        ssid = name
                    else:
                        base = re.sub(r"\s+\d+$", "", name)
                        ssid = base if base in profs else name
            if ssid:
                pw = _win_password(ssid)
        elif sys.platform == "darwin":
            for dev in ("en0", "en1"):
                out = _run("networksetup -getairportnetwork %s" % dev)
                if ":" in out and "not associated" not in out.lower():
                    ssid = out.split(":", 1)[1].strip()
                    break
    except Exception as e:
        print("  (Wi-Fi prepoznavanje:", e, ")")
    return ssid, pw


def wifi_qr_text():
    w = STATE.get("wifi") or {}
    ssid = w.get("ssid", "")
    if not ssid:
        return ""
    def e(x):
        return "".join("\\" + c if c in '\\;,:"' else c for c in x)
    pw = w.get("password", "")
    if pw:
        return "WIFI:T:WPA;S:%s;P:%s;;" % (e(ssid), e(pw))
    return "WIFI:T:nopass;S:%s;;" % e(ssid)


def fix_windows_firewall():
    """Otvara Windows Firewall za Python i portove programa (traži 'Da' u Windows prozoru)."""
    if os.name != "nt":
        return
    import subprocess
    import tempfile
    try:
        r = subprocess.run('netsh advfirewall firewall show rule name="Karaoke glasanje"',
                           shell=True, capture_output=True)
        if r.returncode == 0:
            return
    except Exception:
        pass
    exe = sys.executable
    ports = ",".join(str(x) for x in PORTS)
    bat = os.path.join(tempfile.gettempdir(), "karaoke_firewall.bat")
    with open(bat, "w") as f:
        f.write("@echo off\n")
        # makni stare BLOKIRAJUCE pravila za Python (nastaju kad se Windows upit odbije)
        f.write('netsh advfirewall firewall delete rule name=all program="%s"\n' % exe)
        f.write('netsh advfirewall firewall add rule name="Karaoke glasanje" dir=in action=allow '
                'program="%s" enable=yes profile=any\n' % exe)
        f.write('netsh advfirewall firewall add rule name="Karaoke glasanje port" dir=in action=allow '
                'protocol=TCP localport=%s profile=any\n' % ports)
    print("  ➜ Windows će sad pitati smije li program napraviti promjene.")
    print("    Stisni  DA  (Yes). To otvara vatrozid da mobiteli mogu glasati.")
    try:
        import ctypes
        rc = ctypes.windll.shell32.ShellExecuteW(None, "runas", bat, None, None, 0)
        if rc <= 32:
            print("  ⚠ Nisi dopustio promjenu. Mobiteli se možda neće moći spojiti.")
            return
        for _ in range(20):
            time.sleep(1)
            r = subprocess.run('netsh advfirewall firewall show rule name="Karaoke glasanje"',
                               shell=True, capture_output=True)
            if r.returncode == 0:
                print("  ✓ Vatrozid otvoren.")
                return
    except Exception as e:
        print("  ⚠ Ne mogu otvoriti vatrozid:", e)




class Handler(BaseHTTPRequestHandler):
    server_version = "Karaoke/2.0"

    def log_message(self, *args):
        pass

    def is_admin(self, qs):
        host = self.client_address[0]
        if host in ("127.0.0.1", "::1", "::ffff:127.0.0.1"):
            return True
        k = self.headers.get("X-Key") or (qs.get("key") or [""])[0]
        return secrets.compare_digest(k, KEY)

    def send(self, code, body, ctype="application/json; charset=utf-8"):
        if isinstance(body, (dict, list)):
            body = json.dumps(body, ensure_ascii=False)
        data = body.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(data)

    def html(self, page):
        self.send(200, page.replace("/*CSS*/", CSS).replace("/*QRLIB*/", QRLIB), "text/html; charset=utf-8")

    def body(self):
        try:
            n = min(int(self.headers.get("Content-Length", 0)), 20000)
            return json.loads(self.rfile.read(n).decode("utf-8") or "{}")
        except Exception:
            return {}

    def do_GET(self):
        u = urlparse(self.path)
        qs = parse_qs(u.query)
        path = u.path.rstrip("/") or "/"
        if path == "/":
            ip = self.client_address[0]
            if ip not in SEEN and not ip.startswith("127."):
                SEEN.add(ip)
                print("  📱 Spojio se mobitel (%s). Ukupno: %d" % (ip, len(SEEN)))
            return self.html(GUEST_HTML)
        if path == "/ekran":
            return self.html(SCREEN_HTML)
        if path == "/admin":
            if not self.is_admin(qs):
                return self.send(403, "Pristup samo za voditelja.", "text/plain; charset=utf-8")
            return self.html(ADMIN_HTML)
        if path == "/api/state":
            with LOCK:
                return self.send(200, public_state((qs.get("v") or [""])[0][:64]))
        if path == "/api/info":
            w = STATE.get("wifi") or {}
            return self.send(200, {"guestUrl": GUEST_URL, "wifiQr": wifi_qr_text() if w.get("show", True) else "",
                                   "ssid": w.get("ssid", ""), "password": w.get("password", "")})
        if path == "/api/admin/state":
            if not self.is_admin(qs):
                return self.send(403, {"error": "forbidden"})
            with LOCK:
                return self.send(200, admin_state())
        self.send(404, "Nema te stranice.", "text/plain; charset=utf-8")

    def do_POST(self):
        u = urlparse(self.path)
        qs = parse_qs(u.query)
        d = self.body()
        if u.path == "/api/vote":
            voter = str(d.get("voter", ""))[:64]
            try:
                r = int(d.get("rating"))
            except Exception:
                r = 0
            with LOCK:
                p = find(d.get("pid"))
                if not voter or not p or r < 1 or r > 5:
                    return self.send(400, {"error": "Neispravan glas."})
                if STATE["phase"] != "open":
                    return self.send(409, {"error": "Glasanje je zatvoreno.", "state": public_state(voter)})
                p["votes"][voter] = r
                save_state()
                return self.send(200, {"ok": True, "state": public_state(voter)})
        if u.path == "/api/admin/action":
            if not self.is_admin(qs):
                return self.send(403, {"error": "forbidden"})
            with LOCK:
                err = admin_action(d)
                if err:
                    return self.send(400, {"error": err})
                return self.send(200, admin_state())
        self.send(404, {"error": "not found"})


