#rv{position:fixed;inset:0;background:var(--bg);display:none;flex-direction:column;align-items:center;justify-content:center;text-align:center;z-index:50;padding:3vw}
#rv .c{font-size:30vh;font-weight:900;color:var(--pink);animation:pop .4s}
#rv .pl{font-size:clamp(28px,4vw,64px);font-weight:900;animation:pop .4s}
#rv .nm{font-size:clamp(50px,9vw,150px);font-weight:900;line-height:1;margin:2vh 0;animation:pop .5s}
